	private class LogFileWriter : PrintWriter {
		private Path file;

		LogFileWriter(Path logFile)
    : base(new BufferedWriter(new OutputStreamWriter(Files.newOutputStream(logFile))))
    {
			this.file = logFile;
		}

		Path getFile() {
			return file;
		}

		bool isEmpty() {
			try {
				return Files.size(file) == 0;
			}
			catch (IOException e) {
				return true;
			}
		}

		void delete() {
			try {
				Files.delete(file);
			}
			catch (IOException e) {
				// ignore
			}
		}
	}
}
